import React from "react"
import { Link } from "gatsby"
import { CodeBracketIcon, GamepadIcon, MotionGraphicsIcon } from "./Icons"

const FALLBACK_IMAGE =
  "https://placehold.co/960x720/E8EEF8/0F172A?text=Silbaram+Studio"

const TYPE_META = {
  app: {
    label: "Web App",
    accent: "#f97316",
    accentBg: "rgba(249, 115, 22, 0.12)",
    Icon: CodeBracketIcon,
  },
  game: {
    label: "Game Lab",
    accent: "#0f766e",
    accentBg: "rgba(15, 118, 110, 0.12)",
    Icon: GamepadIcon,
  },
  motion: {
    label: "Motion Study",
    accent: "#2563eb",
    accentBg: "rgba(37, 99, 235, 0.12)",
    Icon: MotionGraphicsIcon,
  },
}

const formatRank = rank => (rank ? String(rank).padStart(2, "0") : null)

const CardMeta = ({ project, rank }) => {
  const { label, accent, accentBg, Icon } =
    TYPE_META[project.type] ?? TYPE_META.app

  return (
    <div className="flex items-center justify-between gap-4 text-[0.72rem] font-semibold uppercase tracking-[0.22em] text-[var(--muted)]">
      <div className="flex items-center gap-3">
        <div
          className="flex h-10 w-10 items-center justify-center rounded-2xl border border-[var(--line)]"
          style={{ color: accent, background: accentBg }}
        >
          <Icon />
        </div>
        <span>{label}</span>
      </div>
      {rank ? (
        <span className="rounded-full border border-[var(--line)] px-3 py-1 text-[0.64rem] text-[var(--ink)]">
          #{formatRank(rank)}
        </span>
      ) : null}
    </div>
  )
}

const TagList = ({ tags }) => (
  <div className="flex flex-wrap gap-2">
    {tags.map(tag => (
      <span
        key={tag}
        className="rounded-full border border-[var(--line)] bg-[rgba(255,255,255,0.7)] px-3 py-1 text-[0.68rem] font-semibold uppercase tracking-[0.18em] text-[var(--muted)]"
      >
        {tag}
      </span>
    ))}
  </div>
)

const ImageBlock = ({ project, className, overlay = false }) => (
  <div
    className={`relative overflow-hidden bg-[var(--page-deep)] ${className}`}
  >
    <img
      src={project.imageUrl}
      alt={project.title}
      className="h-full w-full object-cover transition duration-700 ease-out group-hover:scale-105"
      onError={event => {
        event.currentTarget.onerror = null
        event.currentTarget.src = FALLBACK_IMAGE
      }}
    />
    {overlay ? (
      <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-[rgba(15,23,42,0.18)] via-transparent to-transparent" />
    ) : null}
  </div>
)

const ActionRow = ({ label }) => (
  <div className="flex items-center justify-between border-t border-[var(--line)] pt-4 text-sm font-semibold text-[var(--ink)]">
    <span>{label}</span>
    <span className="inline-block text-[var(--accent-soft)] transition duration-300 group-hover:translate-x-1">
      Launch
    </span>
  </div>
)

const ProjectCard = ({
  project,
  variant = "mosaic",
  issueNumber,
  className = "",
}) => {
  const linkClasses = `group block h-full ${className}`.trim()

  if (variant === "lead") {
    return (
      <Link
        to={project.demoUrl}
        state={{ isFullscreen: false }}
        className={linkClasses}
      >
        <article className="paper-panel h-full overflow-hidden rounded-[2rem] p-4 sm:p-5">
          <div className="grid h-full gap-5 lg:grid-cols-[1.06fr_0.94fr]">
            <div className="relative min-h-[20rem] overflow-hidden rounded-[1.6rem]">
              <ImageBlock
                project={project}
                className="absolute inset-0 h-full w-full"
                overlay
              />
              <div className="absolute left-4 top-4 rounded-full bg-[rgba(255,255,255,0.84)] px-4 py-2 text-[0.68rem] font-bold uppercase tracking-[0.24em] text-[var(--accent-deep)]">
                Featured Project
              </div>
            </div>

            <div className="flex flex-col justify-between gap-6 p-3 sm:p-5">
              <div className="space-y-5">
                <CardMeta project={project} rank={issueNumber} />
                <div className="space-y-4">
                  <h3 className="headline-display text-4xl text-[var(--ink)] sm:text-5xl">
                    {project.title}
                  </h3>
                  <p className="max-w-xl text-sm leading-7 text-[var(--muted)] sm:text-base">
                    {project.description}
                  </p>
                </div>
              </div>

              <div className="space-y-5">
                <TagList tags={project.tags} />
                <ActionRow label="Open featured build" />
              </div>
            </div>
          </div>
        </article>
      </Link>
    )
  }

  if (variant === "feature") {
    return (
      <Link
        to={project.demoUrl}
        state={{ isFullscreen: false }}
        className={linkClasses}
      >
        <article className="paper-panel flex h-full flex-col overflow-hidden rounded-[2rem]">
          <div className="relative">
            <ImageBlock project={project} className="h-60 rounded-t-[2rem]" />
            <div className="absolute left-4 top-4 rounded-full bg-[rgba(15,23,42,0.74)] px-3 py-2 text-[0.64rem] font-semibold uppercase tracking-[0.2em] text-white">
              Spotlight
            </div>
          </div>

          <div className="flex flex-1 flex-col gap-5 p-6">
            <CardMeta project={project} rank={issueNumber} />
            <div className="space-y-3">
              <h3 className="headline-serif text-3xl font-semibold leading-tight text-[var(--ink)]">
                {project.title}
              </h3>
              <p className="text-sm leading-7 text-[var(--muted)]">
                {project.description}
              </p>
            </div>
            <div className="mt-auto space-y-4">
              <TagList tags={project.tags} />
              <ActionRow label="Open project" />
            </div>
          </div>
        </article>
      </Link>
    )
  }

  return (
    <Link
      to={project.demoUrl}
      state={{ isFullscreen: false }}
      className={linkClasses}
    >
      <article className="paper-panel flex h-full flex-col overflow-hidden rounded-[1.75rem]">
        <ImageBlock project={project} className="h-48 rounded-t-[1.75rem]" />
        <div className="flex flex-1 flex-col gap-4 p-5">
          <CardMeta project={project} rank={issueNumber} />
          <div className="space-y-3">
            <h3 className="headline-serif text-2xl font-semibold leading-tight text-[var(--ink)]">
              {project.title}
            </h3>
            <p className="text-sm leading-6 text-[var(--muted)]">
              {project.description}
            </p>
          </div>
          <div className="mt-auto space-y-4">
            <TagList tags={project.tags} />
            <ActionRow label="View project" />
          </div>
        </div>
      </article>
    </Link>
  )
}

export default ProjectCard
