import React, { useState } from "react"
import { Link } from "gatsby"
import ProjectCard from "./ProjectCard"

const FILTERS = [
  { id: "all", label: "All" },
  { id: "game", label: "Games" },
  { id: "app", label: "Apps" },
  { id: "motion", label: "Motion" },
]

const FILTER_COPY = {
  all: "A tighter, more polished landing page for browser tools, games, and motion experiments.",
  game: "Playable browser experiments with a sharper showcase-first layout.",
  app: "Useful tools presented like product launches instead of plain utility links.",
  motion:
    "Visual studies and motion demos framed as premium interactive pieces.",
}

const SHOWCASE_PRIORITY = {
  "motion-1": 0,
  "game-2": 1,
  "game-1": 2,
  "app-2": 3,
  "motion-2": 4,
  "app-1": 5,
  "app-3": 6,
}

const delayClassForIndex = index => {
  const delayClasses = [
    "",
    "stagger-delay-1",
    "stagger-delay-2",
    "stagger-delay-3",
  ]
  return delayClasses[index % delayClasses.length]
}

const formatCount = count => String(count).padStart(2, "0")

const buildCounts = projects => ({
  all: projects.length,
  game: projects.filter(project => project.type === "game").length,
  app: projects.filter(project => project.type === "app").length,
  motion: projects.filter(project => project.type === "motion").length,
})

const ProjectList = ({ projects }) => {
  const [searchTerm, setSearchTerm] = useState("")
  const [activeFilter, setActiveFilter] = useState("all")

  const normalizedSearchTerm = searchTerm.trim().toLowerCase()
  const countsByFilter = buildCounts(projects)

  const filteredProjects = projects.filter(project => {
    const matchesSearch =
      project.title.toLowerCase().includes(normalizedSearchTerm) ||
      project.description.toLowerCase().includes(normalizedSearchTerm)

    const matchesFilter =
      activeFilter === "all" || project.type === activeFilter

    return matchesSearch && matchesFilter
  })

  const showcaseProjects = [...filteredProjects].sort(
    (left, right) =>
      (SHOWCASE_PRIORITY[left.id] ?? Number.MAX_SAFE_INTEGER) -
      (SHOWCASE_PRIORITY[right.id] ?? Number.MAX_SAFE_INTEGER)
  )

  const leadProject = showcaseProjects[0]
  const secondaryProjects = showcaseProjects.slice(1, 3)
  const gridProjects = showcaseProjects.slice(3)
  const quickAccessProjects = (
    showcaseProjects.length > 0 ? showcaseProjects : projects
  ).slice(0, 3)
  const updatedOn = new Intl.DateTimeFormat("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  }).format(new Date())

  return (
    <div className="mx-auto max-w-7xl px-4 pb-16 pt-6 sm:px-6 lg:px-8 lg:pb-20 lg:pt-8">
      <section className="paper-panel stagger-in relative overflow-hidden rounded-[2.5rem] p-8 sm:p-10 lg:p-12">
        <div className="absolute inset-0 overflow-hidden">
          <div className="absolute -left-20 top-10 h-56 w-56 rounded-full bg-[rgba(37,99,235,0.12)] blur-3xl" />
          <div className="absolute right-10 top-16 h-44 w-44 rounded-full bg-[rgba(249,115,22,0.16)] blur-3xl" />
          <div className="absolute bottom-0 left-1/3 h-48 w-48 rounded-full bg-[rgba(15,118,110,0.14)] blur-3xl" />
        </div>

        <div className="relative z-10 grid gap-8 xl:grid-cols-[1.18fr_0.82fr]">
          <div>
            <p className="section-kicker">
              Silbaram Studio / Updated {updatedOn}
            </p>
            <h1 className="headline-display mt-6 max-w-5xl text-[clamp(3.4rem,9vw,7rem)] text-[var(--ink)]">
              Interactive projects with a cleaner, more stylish front page.
            </h1>
            <p className="mt-6 max-w-2xl text-base leading-7 text-[var(--muted)] sm:text-lg">
              {FILTER_COPY[activeFilter]}
            </p>

            <div className="mt-8 flex flex-wrap gap-3">
              <a
                href="#projects"
                className="editorial-link rounded-full bg-[var(--ink)] px-6 py-3 text-sm font-semibold text-white shadow-[0_16px_32px_rgba(15,23,42,0.18)]"
              >
                Explore Projects
              </a>
              {leadProject ? (
                <Link
                  to={leadProject.demoUrl}
                  state={{ isFullscreen: false }}
                  className="editorial-link paper-inset rounded-full px-6 py-3 text-sm font-semibold text-[var(--ink)]"
                >
                  Open Featured
                </Link>
              ) : null}
            </div>

            <div className="mt-10 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
              {[
                { label: "Projects", value: formatCount(projects.length) },
                { label: "Games", value: formatCount(countsByFilter.game) },
                { label: "Apps", value: formatCount(countsByFilter.app) },
                { label: "Motion", value: formatCount(countsByFilter.motion) },
              ].map(item => (
                <div
                  key={item.label}
                  className="paper-inset rounded-[1.4rem] px-4 py-5"
                >
                  <p className="text-xs font-semibold uppercase tracking-[0.22em] text-[var(--muted)]">
                    {item.label}
                  </p>
                  <p className="headline-serif mt-2 text-3xl text-[var(--ink)]">
                    {item.value}
                  </p>
                </div>
              ))}
            </div>
          </div>

          <div className="space-y-5">
            <div className="paper-inset stagger-in stagger-delay-1 rounded-[2rem] p-6">
              <p className="section-kicker">Featured Right Now</p>
              <h2 className="headline-serif mt-4 text-3xl leading-tight text-[var(--ink)]">
                {leadProject ? leadProject.title : "Project showcase"}
              </h2>
              <p className="mt-4 text-sm leading-7 text-[var(--muted)]">
                {leadProject
                  ? leadProject.description
                  : "Pick a filter or use search to bring a featured project into focus."}
              </p>

              <div className="mt-6 grid grid-cols-3 gap-3">
                {[
                  {
                    label: "Visible",
                    value: formatCount(filteredProjects.length),
                  },
                  { label: "Active", value: activeFilter.toUpperCase() },
                  { label: "Search", value: searchTerm ? "ON" : "OFF" },
                ].map(stat => (
                  <div
                    key={stat.label}
                    className="rounded-[1.2rem] bg-[rgba(255,255,255,0.72)] px-3 py-4 text-center"
                  >
                    <p className="text-[0.62rem] font-semibold uppercase tracking-[0.22em] text-[var(--muted)]">
                      {stat.label}
                    </p>
                    <p className="headline-serif mt-2 text-2xl text-[var(--ink)]">
                      {stat.value}
                    </p>
                  </div>
                ))}
              </div>
            </div>

            <div className="paper-inset stagger-in stagger-delay-2 rounded-[2rem] p-6">
              <p className="section-kicker">Quick Access</p>
              <div className="mt-5 space-y-4">
                {quickAccessProjects.map((project, index) => (
                  <Link
                    key={project.id}
                    to={project.demoUrl}
                    state={{ isFullscreen: false }}
                    className="editorial-link flex items-start justify-between gap-4 rounded-[1.2rem] border border-[var(--line)] bg-[rgba(255,255,255,0.58)] px-4 py-4"
                  >
                    <div>
                      <p className="text-[0.65rem] font-semibold uppercase tracking-[0.2em] text-[var(--accent-deep)]">
                        Featured {formatCount(index + 1)}
                      </p>
                      <p className="headline-serif mt-2 text-xl font-semibold text-[var(--ink)]">
                        {project.title}
                      </p>
                    </div>
                    <span className="text-sm font-semibold text-[var(--accent-soft)]">
                      Open
                    </span>
                  </Link>
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>

      <section className="mt-8 grid gap-6 lg:grid-cols-[1.18fr_0.82fr]">
        <div className="paper-panel stagger-in stagger-delay-1 rounded-[2rem] p-6">
          <p className="section-kicker">Filter Projects</p>
          <div className="mt-5 flex flex-col gap-4 lg:flex-row lg:items-center">
            <label className="block flex-1">
              <span className="sr-only">Search projects</span>
              <div className="paper-inset flex items-center gap-3 rounded-full px-4 py-3">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  viewBox="0 0 20 20"
                  fill="currentColor"
                  className="h-5 w-5 text-[var(--muted)]"
                >
                  <path
                    fillRule="evenodd"
                    d="M9 3.5a5.5 5.5 0 1 0 3.49 9.75l3.63 3.63a1 1 0 0 0 1.41-1.42l-3.62-3.62A5.5 5.5 0 0 0 9 3.5ZM5.5 9a3.5 3.5 0 1 1 7 0a3.5 3.5 0 0 1-7 0Z"
                    clipRule="evenodd"
                  />
                </svg>
                <input
                  type="text"
                  placeholder="Search by title or description"
                  value={searchTerm}
                  onChange={event => setSearchTerm(event.target.value)}
                  className="w-full bg-transparent text-sm text-[var(--ink)] outline-none placeholder:text-[var(--muted)]"
                />
              </div>
            </label>

            <div className="flex flex-wrap gap-2">
              {FILTERS.map(filter => {
                const isActive = activeFilter === filter.id

                return (
                  <button
                    key={filter.id}
                    type="button"
                    onClick={() => setActiveFilter(filter.id)}
                    aria-pressed={isActive}
                    className={`rounded-full px-4 py-2 text-sm font-semibold transition ${
                      isActive
                        ? "bg-[var(--ink)] text-white shadow-[0_14px_30px_rgba(15,23,42,0.18)]"
                        : "paper-inset text-[var(--ink)] hover:-translate-y-0.5"
                    }`}
                  >
                    {filter.label}
                    <span
                      className={`ml-2 ${
                        isActive ? "text-white/70" : "text-[var(--muted)]"
                      }`}
                    >
                      {formatCount(countsByFilter[filter.id])}
                    </span>
                  </button>
                )
              })}
            </div>
          </div>
        </div>

        <div className="paper-panel stagger-in stagger-delay-2 rounded-[2rem] p-6">
          <p className="section-kicker">Current View</p>
          <h2 className="headline-serif mt-4 text-3xl leading-tight text-[var(--ink)]">
            {activeFilter === "all"
              ? "All categories are visible."
              : `${
                  FILTERS.find(filter => filter.id === activeFilter)?.label
                } are in focus.`}
          </h2>
          <p className="mt-4 text-sm leading-7 text-[var(--muted)]">
            {FILTER_COPY[activeFilter]}
          </p>
          <div className="mt-6 flex flex-wrap gap-3">
            <div className="paper-inset rounded-full px-4 py-2 text-sm font-semibold text-[var(--ink)]">
              {formatCount(filteredProjects.length)} results
            </div>
            <div className="paper-inset rounded-full px-4 py-2 text-sm font-semibold text-[var(--ink)]">
              Search: {searchTerm ? "active" : "idle"}
            </div>
          </div>
        </div>
      </section>

      {showcaseProjects.length > 0 ? (
        <>
          {leadProject ? (
            <section id="projects" className="mt-12">
              <div className="mb-6 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
                <div>
                  <p className="section-kicker">Featured Showcase</p>
                  <h2 className="headline-serif mt-3 text-4xl text-[var(--ink)]">
                    Start with the strongest projects.
                  </h2>
                </div>
                <p className="max-w-2xl text-sm leading-7 text-[var(--muted)]">
                  The first row is reserved for the standout demos, followed by
                  the rest of the collection in a cleaner browsing grid.
                </p>
              </div>

              <div
                className={`grid gap-6 ${
                  secondaryProjects.length > 0
                    ? "lg:grid-cols-[1.08fr_0.92fr]"
                    : ""
                }`}
              >
                <ProjectCard
                  project={leadProject}
                  variant="lead"
                  issueNumber={1}
                  className="stagger-in"
                />

                {secondaryProjects.length > 0 ? (
                  <div className="grid gap-6">
                    {secondaryProjects.map((project, index) => (
                      <ProjectCard
                        key={project.id}
                        project={project}
                        variant="feature"
                        issueNumber={index + 2}
                        className={`stagger-in ${delayClassForIndex(
                          index + 1
                        )}`.trim()}
                      />
                    ))}
                  </div>
                ) : null}
              </div>
            </section>
          ) : null}

          {gridProjects.length > 0 ? (
            <section className="mt-14">
              <div className="mb-6 flex flex-col gap-4 border-t border-[var(--line)] pt-6 lg:flex-row lg:items-end lg:justify-between">
                <div>
                  <p className="section-kicker">Project Grid</p>
                  <h2 className="headline-serif mt-3 text-4xl text-[var(--ink)]">
                    Explore the rest of the lineup.
                  </h2>
                </div>
                <p className="max-w-2xl text-sm leading-7 text-[var(--muted)]">
                  Cleaner cards, clearer actions, and less editorial styling so
                  the homepage reads more like a modern showcase.
                </p>
              </div>

              <div className="grid gap-6 md:grid-cols-2 xl:grid-cols-3">
                {gridProjects.map((project, index) => {
                  const spanClass =
                    index === 0 && gridProjects.length > 2
                      ? "md:col-span-2 xl:col-span-2"
                      : ""

                  return (
                    <ProjectCard
                      key={project.id}
                      project={project}
                      issueNumber={index + 4}
                      className={`stagger-in ${delayClassForIndex(
                        index
                      )} ${spanClass}`.trim()}
                    />
                  )
                })}
              </div>
            </section>
          ) : null}
        </>
      ) : (
        <section id="projects" className="mt-12">
          <div className="paper-panel rounded-[2rem] p-8 text-center">
            <p className="section-kicker">No Results</p>
            <h2 className="headline-serif mt-4 text-4xl text-[var(--ink)]">
              Nothing matches the current filter.
            </h2>
            <p className="mx-auto mt-4 max-w-xl text-sm leading-7 text-[var(--muted)]">
              Reset the search and category filter to bring the full project
              list back into view.
            </p>
            <button
              type="button"
              onClick={() => {
                setSearchTerm("")
                setActiveFilter("all")
              }}
              className="editorial-link mt-8 rounded-full bg-[var(--ink)] px-6 py-3 text-sm font-semibold text-white shadow-[0_16px_32px_rgba(15,23,42,0.18)]"
            >
              Reset Filters
            </button>
          </div>
        </section>
      )}
    </div>
  )
}

export default ProjectList
